```cpp
#include <iostream>
#include <string>
using namespace std;

class Car {  // Class definition
public:
    string brand;
    int year;

    void display() {  // Method
        cout << "Brand: " << brand << ", Year: " << year << endl;
    }
};

int main() {
    Car myCar;  // Object creation
    myCar.brand = "Toyota";
    myCar.year = 2020;
    myCar.display();  // Method call
    return 0;
}
```
Output:
`Brand: Toyota, Year: 2020`
